local config = {
  ui_story_31000101_1_dialog_content = "Hah? Kamu memanggilku?",
  ui_story_31000101_2_dialog_content = "Aku masih belum terbiasa dipanggil bocah polos...",
  ui_story_31000101_3_dialog_content = "Tak apa. Kamu punya otak yang sedikit lebih besar daripada paramecia itu, jadi aku yakin kamu akan terbiasa.",
  ui_story_31000101_4_dialog_content = "Apakah ini mungkin, barangkali, bisa jadi kamu memujiku?",
  ui_story_31000101_5_dialog_content = "Tentu saja. Kamu benar-benar berbeda dari yang lain.",
  ui_story_31000101_6_dialog_content = "Itulah sebabnya, aku ingin berbicara denganmu.",
  ui_story_31000101_7_dialog_content = "Baiklah, aku bisa kalau hanya berbicara.",
  ui_story_31000101_8_dialog_content = "Tapi baru saja kamu memintaku untuk menceritakan sebuah kisah... dan sepertinya aku tak bisa memikirkan kisahku sendiri untuk diceritakan.",
  ui_story_31000101_9_dialog_content = "Benarkah? Sayang sekali.",
  ui_story_31000101_10_dialog_content = "Kalau begitu, biarkan aku bercerita.",
  ui_story_31000101_11_dialog_content = "Hah? Kisah tentangmu? Aku siap mendengar.",
  ui_story_31000101_12_dialog_content = "Yah, ini kisah tentang kebenaran.",
  ui_story_31000101_13_option_content = "Tunggu... Jika kisahnya hanya tentang kebenaran, tak usah...",
  ui_story_31000101_14_dialog_content = "Oh? Jadi, kamu tidak tertarik sama sekali?",
  ui_story_31000101_15_dialog_content = "Aku tak begitu pintar... Jika kamu mencoba mengajariku tentang kebenaran, ini akan menjadi tugas yang sulit bagimu...",
  ui_story_31000101_16_dialog_content = "Baiklah, baiklah. Aku mengerti maksudmu.",
  ui_story_31000101_17_dialog_content = "Kita ganti topik saja. Apa pendapatmu tentang makam dan harta karunnya?",
  ui_story_31000101_18_dialog_content = "Harta karun? Begitu, dong!",
  ui_story_31000101_19_option_content = "Akulah kebenaran!",
  ui_story_31000101_20_dialog_content = "Kamu?",
  ui_story_31000101_21_dialog_content = "Begitu, ya... Aku tahu Lady Victoria menganggap kamu ini spesial, tapi kamu tidak begitu sesuai dengan apa yang aku anggap sebagai kebenaran ideal bagiku.",
  ui_story_31000101_22_dialog_content = "Mungkin kamu tidak melihat dengan cukup cermat.",
  ui_story_31000101_23_dialog_content = "Lupakan... Kita ganti topik saja. Apa pendapatmu tentang makam dan harta karunnya?",
  ui_story_31000101_24_dialog_content = "Kedengarannya menarik!",
  ui_story_31000101_25_dialog_content = "Benar, berkilauan dan tak ternilai harganya...",
  ui_story_31000101_26_dialog_content = "Harta karun yang tersembunyi di makam kuno bahkan mungkin adalah relik peradaban kuno...",
  ui_story_31000101_27_dialog_content = "Tidak hanya kamu, bocah polos. Banyak orang tertarik dengan harta karun seperti itu.",
  ui_story_31000101_28_dialog_content = "Aku pernah bertemu orang macam itu, yang menyelinap ke makam-makam ini untuk mencuri harta karun di dalamnya.",
  ui_story_31000101_29_dialog_content = "Hah? Penjarah makam?",
  ui_story_31000101_30_dialog_content = "Betul. Mengendap-endap dengan membawa sekarung barang, mencoba menyelinap masuk ke makam dan menjarah hingga habis.",
  ui_story_31000101_31_dialog_content = "Saat aku menemuinya, dia sangat ketakutan hingga hampir pingsan.",
  ui_story_31000101_32_dialog_content = "Bagi pencuri, bertemu denganmu sama saja seperti bertemu dengan polisi...",
  ui_story_31000101_33_dialog_content = "Kamu menangkapnya?",
  ui_story_31000101_34_dialog_content = "Menangkap dia?",
  ui_story_31000101_35_dialog_content = "Aku tak punya waktu...",
  ui_story_31000101_36_dialog_content = "Aku hanya ingin dia menceritakan kisah-kisahnya selama sepuluh hari sepuluh malam.",
  ui_story_31000101_37_option_content = "Kamu punya waktu untuk mendengarkan kisah-kisahnya?",
  ui_story_31000101_38_dialog_content = "Tidak ada hal lain yang bisa kulakukan di dalam makam itu.",
  ui_story_31000101_39_dialog_content = "Aku ingin tahu lebih banyak, tentang dunia luar, langit yang selalu berubah, pepohonan yang menggugurkan daunnya, dan...",
  ui_story_31000101_40_dialog_content = "Orang-orang di negeri ini.",
  ui_story_31000101_41_dialog_content = "Aku ingin dia menceritakan tentang hal-hal ini.",
  ui_story_31000101_42_option_content = "Kalian berdua menghabiskan sepuluh hari sepuluh malam bersama di sebuah makam?",
  ui_story_31000101_43_dialog_content = "Ya. Itu belum cukup lama.",
  ui_story_31000101_44_dialog_content = "Jika dia tidak kehabisan kata-kata untuk diucapkan, aku bisa tinggal lebih lama lagi.",
  ui_story_31000101_45_dialog_content = "Sayangnya, dia menyelesaikan semua cerita yang dia tahu, dan itulah akhirnya.",
  ui_story_31000101_46_dialog_content = "Kamu sangat suka mendengarkan orang bercerita, ya, Sikare Dantes?",
  ui_story_31000101_47_dialog_content = "(Tiba-tiba aku merasakan kesepian Sikare Dantes...)",
  ui_story_31000101_48_dialog_content = "Ada apa, bocah polos? Ada apa dengan ekspresi yang tiba-tiba muncul itu?",
  ui_story_31000101_49_dialog_content = "Oh, tak apa... Jadi, dari cerita-cerita yang kamu dengar selama sepuluh hari dan sepuluh malam itu, mana yang menjadi favoritmu?",
  ui_story_31000101_50_dialog_content = "Oh, ada begitu banyak!",
  ui_story_31000101_51_dialog_content = "Salah satu ceritanya adalah saat dia tersesat di Northland.",
  ui_story_31000101_52_dialog_content = "Dia bercerita bahwa dia berhadapan dengan badai salju di sana.",
  ui_story_31000101_53_dialog_content = "Untuk keluar dari salju, dia berjalan terus melawan angin yang dingin, dan akhirnya memasuki hutan.",
  ui_story_31000101_54_dialog_content = "Dia tidak bisa melihat langit karena pepohonannya, dan dia tidak bisa membedakan satu arah dengan yang lain, jadi dia menandai tanah agar tidak berputar-putar tanpa tujuan.",
  ui_story_31000101_55_dialog_content = "Tapi setelah berjalan lama... Dia tiba-tiba melihat tanda yang dia buat sebelumnya di jalan di depannya.",
  ui_story_31000101_56_dialog_content = "Wow! Dia mulai jalan berputar-putar!?",
  ui_story_31000101_57_dialog_content = "Tidak... Menurutnya, dia tidak berbelok sama sekali, dan terus berjalan lurus.",
  ui_story_31000101_58_dialog_content = "Terlebih lagi, saat dia akhirnya menyadari bahwa tanda-tandanya tidak hanya di jalan di depannya itu saja... Dia melihat tandanya di kiri, kanan, dan di belakangnya juga.",
  ui_story_31000101_59_dialog_content = "Itu... menakutkan sekali!",
  ui_story_31000101_60_dialog_content = "Memang iya. Saat mendengarkan ini, aku bahkan terlalu takut untuk melepaskan pelukan pada kerangka di makam itu.",
  ui_story_31000101_61_dialog_content = "Argh... Lain kali peluk sesuatu yang lain saja...",
  ui_story_31000101_62_dialog_content = "Tapi kemudian, tiba-tiba dia melihat pohon di depannya bergetar, dan sesosok bertubuh kecil muncul.",
  ui_story_31000101_63_dialog_content = "Tadinya dia mengira itu Eclipsite... Tapi kemudian dia menyadari bahwa sosok itu adalah anak kecil.",
  ui_story_31000101_64_dialog_content = "Anak manis dengan wajah merah dan mata besar yang menatap lurus ke arahnya.",
  ui_story_31000101_65_dialog_content = "Anak itu bertanya apakah dia tersesat.",
  ui_story_31000101_66_dialog_content = "Dia menjawab ya, dan ekspresi simpati terlihat di wajah anak itu.",
  ui_story_31000101_67_option_content = "Anak ini sangat... mencurigakan!",
  ui_story_31000101_68_dialog_content = "Itu yang kupikirkan!",
  ui_story_31000101_69_option_content = "Apakah anak itu... sebuah ilusi?",
  ui_story_31000101_70_dialog_content = "Itu juga yang kupikirkan.",
  ui_story_31000101_71_dialog_content = "Namun, dia berkata bahwa saat anak itu mendengar bahwa dia tersesat, anak itu berjalan ke arahnya dan meraih tangannya.",
  ui_story_31000101_72_dialog_content = "Lalu, anak itu berkata padanya, \"Ikutlah denganku.\"",
  ui_story_31000101_73_dialog_content = "Apa!?",
  ui_story_31000101_74_dialog_content = "Mengejutkan, 'kan!",
  ui_story_31000101_75_dialog_content = "Karena tidak punya pilihan lain, dia mengikuti anak itu.",
  ui_story_31000101_76_dialog_content = "Setelah berjalan sekitar setengah jam, dataran seputih salju itu muncul di hadapan mereka.",
  ui_story_31000101_77_dialog_content = "Mereka berhasil keluar dari hutan itu!",
  ui_story_31000101_78_dialog_content = "Ya!",
  ui_story_31000101_79_dialog_content = "Dia sangat bersyukur dan ingin berterima kasih kepada anak itu, tapi saat dia berbalik, anak itu tidak ada.",
  ui_story_31000101_80_dialog_content = "Hanya ada hutan di belakang, salju di depan, dan hanya dia, sendirian di negeri yang luas dan beku itu.",
  ui_story_31000101_81_dialog_content = "Cerita yang aneh sekali!",
  ui_story_31000101_82_dialog_content = "Benar itu bukan ilusi?",
  ui_story_31000101_83_dialog_content = "Ilusi atau bukan... aku tak yakin.",
  ui_story_31000101_84_dialog_content = "Yang jelas, aku sangat menyukai cerita ini.",
  ui_story_31000101_85_dialog_content = "Sebagai imbalannya, aku memberi sesuatu yang dia butuhkan.",
  ui_story_31000101_86_dialog_content = "Apakah itu...",
  ui_story_31000101_87_dialog_content = "Harta karun!?",
  ui_story_31000101_88_dialog_content = "Betul. Cukup untuk membuat hidupnya nyaman sepanjang hayat.",
  ui_story_31000101_89_dialog_content = "Tidak, tidak hanya untuk membuatnya nyaman. Dia mungkin sekarang sudah menggunakan harta karun ini untuk mendapatkan hal-hal yang jauh lebih tinggi daripada yang bisa dibayangkan kebanyakan orang.",
  ui_story_31000101_90_dialog_content = "Sebanyak itu, ya!?",
  ui_story_31000101_91_dialog_content = "Andai aku tahu bisa mendapatkan hadiah yang begitu besar karena menceritakan sebuah kisah kepadamu, aku sudah menceritakannya dari dulu!",
  ui_story_31000101_92_dialog_content = "Menyesali kebodohanmu, bocah polos?",
  ui_story_31000101_93_dialog_content = "Tapi mungkin kamu tidak menginginkan harta karun yang kuberikan padanya, bocah polos.",
  ui_story_31000101_94_dialog_content = "Hah? Harta karun aneh macam apa yang kamu berikan padanya?",
  ui_story_31000101_95_dialog_content = "Tunggu, maksudmu, harta karun di makam itu 'kan dikutuk, jadi...",
  ui_story_31000101_96_dialog_content = "Tolong, jangan gunakan pemikiran sederhana seperti paramecia biasa itu.",
  ui_story_31000101_97_dialog_content = "Aku memberinya harta karun yang melampaui uang, melampaui waktu, melampaui batas-batas peradaban itu sendiri...",
  ui_story_31000101_98_dialog_content = "Aku memberinya rahasia kebenaran.",
  ui_story_31000101_99_option_content = "Jadi, kamu berkhotbah padanya?",
  ui_story_31000101_100_dialog_content = "Kebenaran harus diberikan kepada orang yang pantas. Dan dia layak mendapatkannya.",
  ui_story_31000101_101_option_content = "Jadi, kau membunuhnya?",
  ui_story_31000101_102_dialog_content = "Kematian mungkin merupakan cara baginya untuk menghargai dan menjadi kebenaran, tapi saat itu dia tidak membutuhkannya.",
  ui_story_31000101_103_dialog_content = "Aku memberikan kitab suci True Order kepadanya. Karena dia sudah mengajariku tentang dunia selama sepuluh hari sepuluh malam, maka aku mengajarinya tentang kebenaran selama sepuluh hari sepuluh malam.",
  ui_story_31000101_104_dialog_content = "Mendengarkanmu berbicara tentang kebenaran selama sepuluh hari sepuluh malam... Apakah pria itu masih hidup?",
  ui_story_31000101_105_dialog_content = "Seperti kataku tadi, dia pasti menjalani hidupnya dengan baik.",
  ui_story_31000101_106_dialog_content = "Bukan hanya itu, setelah menerima kebenaran selama sepuluh hari sepuluh malam, dia meraih pencerahan.",
  ui_story_31000101_107_dialog_content = "Sejak saat itu, ia menjadi penyebar kebenaran, menyampaikan ajaran kebenaran kepada orang-orang di seluruh Astra.",
  ui_story_31000101_108_dialog_content = "Selain itu, dia adalah pencerita yang sangat baik...",
  ui_story_31000101_109_dialog_content = "Tentu saja. Lagi pula, dia bercerita padamu selama sepuluh hari sepuluh malam...",
  ui_story_31000101_110_dialog_content = "Inilah sebabnya mengapa interpretasinya akan kebenaran telah dipuji oleh begitu banyak orang.",
  ui_story_31000101_111_dialog_content = "Dia menerima dukungan besar, dan diminta untuk menyebarkan kebenaran ke seluruh dunia. Tentu saja, dia juga diberi makanan dan akomodasi sebagai imbalannya.",
  ui_story_31000101_112_dialog_content = "Jadi, sekarang dia tak perlu khawatir lagi tentang rasa nyaman.",
  ui_story_31000101_113_dialog_content = "Sebagai penyebar kebenaran, dia sudah jauh melampaui tingkat manusia dan paramecia biasa.",
  ui_story_31000101_114_dialog_content = "Yah, kurasa kau memang memberinya harta karun yang sangat berharga...",
  ui_story_31000101_115_dialog_content = "Makanan, minuman, dan tempat untuk tidur... Ada banyak orang yang hanya bisa memimpikan kemewahan seperti itu.",
  ui_story_31000101_116_dialog_content = "Bocah polos, kamu masih bersikeras untuk berpikir seperti paramecia?",
  ui_story_31000101_117_dialog_content = "Maaf, sudah kubilang aku ini tidak terlalu pintar...",
  ui_story_31000101_118_dialog_content = "Yah, kamu bisa memikirkannya untuk saat ini.",
  ui_story_31000101_119_dialog_content = "Tunggu... Apa maksud senyum licikmu itu?",
  ui_story_31000601_1_dialog_content = "Cuaca akhir-akhir ini cukup dingin. Saya tidak melihat banyak orang keluar-masuk, tetapi klinik tetap sibuk seperti biasanya.",
  ui_story_31000601_2_dialog_content = "Setiap layanan memiliki daftar tunggu yang sangat banyak—bahkan antrian untuk mengambil obat pun sulit dipercaya.",
  ui_story_31000601_3_dialog_content = "Apakah Anda, kebetulan, mengeluh tentang menemani saya ke klinik?",
  ui_story_31000601_4_dialog_content = "T-Tidak sama sekali! Maksud saya, dengan semua pasien ini, dokter harus benar-benar sibuk...",
  ui_story_31000601_5_dialog_content = "Anda benar-benar beruntung, Sikare. Saya mendengar mudah sakit ketika musim mulai berubah.",
  ui_story_31000601_6_dialog_content = "Terima kasih atas perhatian Anda, tetapi saya tidak mudah sakit. Saya di sini hanya untuk mengambil resep untuk <color=#FFB400>insomnia</color>.",
  ui_story_31000601_7_dialog_content = "Meskipun saya harus setuju, saya tidak menyangka antriannya akan begitu panjang...",
  ui_story_31000601_8_dialog_content = "Tampaknya kita akan berada di sini untuk beberapa waktu, jadi jika Anda benar-benar ingin mengeluh, saya tidak keberatan.",
  ui_story_31000601_9_option_content = "Insomnia? Maksud kamu apa?",
  ui_story_31000601_10_dialog_content = "Aku lebih mengkhawatirkan kesehatanmu daripada mengantri, Sikare.",
  ui_story_31000601_11_option_content = "Aku akan menunggu denganmu.",
  ui_story_31000601_12_dialog_content = "Saya setuju untuk ikut dengan Anda untuk mengambil obat, jadi tidak akan ada keluhan dari saya.",
  ui_story_31000601_13_dialog_content = "Lagi pula, Anda menyebutkan resep untuk insomnia?",
  ui_story_31000601_14_dialog_content = "Apakah Anda kurang tidur karena sesuatu akhir-akhir ini?",
  ui_story_31000601_15_dialog_content = "... Heh. Saya kira Lady Victoria benar untuk menganggap Anda dengan penghargaan yang begitu tinggi.",
  ui_story_31000601_16_dialog_content = "Untuk mendapatkan tidur nyenyak yang cukup, saya membutuhkan keheningan total, tetapi kuburan cukup berisik akhir-akhir ini.",
  ui_story_31000601_17_dialog_content = "Maksudmu Starry Crypt?",
  ui_story_31000601_18_dialog_content = "Jangan bilang ada sesuatu yang mengganggu tidur mereka...",
  ui_story_31000601_19_dialog_content = "Tebakan Anda bisa jadi benar. Bagaimanapun, Anda adalah salah satu dari Ordo Sejati yang terpilih.",
  ui_story_31000601_20_dialog_content = "Jika demikian, tampaknya saya harus ekstra waspada agar tidak terjadi sesuatu yang mengerikan ...",
  ui_story_31000601_21_dialog_content = "Saya mohon, Dokter! Tolong bantu aku!",
  ui_story_31000601_22_dialog_content = "Biarkan saya menjelaskan diri saya sekali lagi, tolong!",
  ui_story_31000601_23_dialog_content = "Jika Anda tidak membantu saya, saya tidak punya tempat lain untuk berpaling ...",
  ui_story_31000601_24_dialog_content = "Saya sangat menyesal, Bu.",
  ui_story_31000601_25_dialog_content = "Tapi dokter sudah memberitahu Anda bahwa tidak ada yang bisa dia lakukan. Saya harus meminta Anda mencari bantuan di tempat lain.",
  ui_story_31000601_26_dialog_content = "Masih banyak <color=#FFB400>hidup, bernafas orang</color> di belakang Anda menunggu untuk menerima perawatan dari dokter.",
  ui_story_31000601_27_dialog_content = "Mengapa kamu tidak ikut denganku ke lobi, dan kita bisa duduk bersama sampai kamu tenang. Apakah itu baik-baik saja?",
  ui_story_31000601_28_dialog_content = "Seseorang menyebabkan keributan di garis depan...",
  ui_story_31000601_29_dialog_content = "Kedengarannya seperti dokter tidak ingin merawat wanita itu, tetapi sesuatu yang dikatakan perawat menarik perhatianku...",
  ui_story_31000601_30_dialog_content = "Apa sebenarnya yang dia maksud dengan <color=#FFB400>\"orang yang hidup, bernafas\"</color>?",
  ui_story_31000601_31_dialog_content = "Ah, mereka datang.",
  ui_story_31000601_32_dialog_content = "...",
  ui_story_31000601_33_dialog_content = "Tolong... seseorang selamatkan anakku...",
  ui_story_31000601_34_dialog_content = "Sini, duduklah sementara aku mengambilkanmu segelas air.",
  ui_story_31000601_35_dialog_content = "Saya tidak ingin air! Aku ingin seseorang menyelamatkan anakku...",
  ui_story_31000601_36_dialog_content = "Er... Maafkan saya, Nona? Maaf menyela.",
  ui_story_31000601_37_dialog_content = "Bolehkah saya bertanya mengapa dokter tidak mau membantu wanita itu? Dia terlihat sangat tertekan...",
  ui_story_31000601_38_dialog_content = "Juga, bisakah Anda menjelaskan apa yang Anda maksud dengan \"orang yang hidup, bernafas\" sekarang?",
  ui_story_31000601_39_dialog_content = "Dia datang ke klinik setiap pagi selama beberapa hari terakhir, memohon dokter untuk menyelamatkan putranya.",
  ui_story_31000601_40_dialog_content = "Tetapi ketika dokter bertanya ada apa dengan putranya, dia mengatakan bahwa dia sudah mati.",
  ui_story_31000601_41_dialog_content = "Mati...?",
  ui_story_31000601_42_dialog_content = "Jadi dia terus meminta dokter... untuk menyelamatkan anaknya yang sudah meninggal?",
  ui_story_31000601_43_dialog_content = "Itu pasti menjelaskan pilihan kata-kata Anda.",
  ui_story_31000601_44_dialog_content = "Saya bisa mengerti mengapa dokter mengatakan dia tidak bisa membantu.",
  ui_story_31000601_45_dialog_content = "Selanjutnya, dia mengatakan bahwa putranya meninggal di rumah berhantu.",
  ui_story_31000601_46_dialog_content = "Dia ingin dokter pergi ke rumah hantu dan memeriksa mayatnya secara pribadi.",
  ui_story_31000601_47_dialog_content = "Namun…",
  ui_story_31000601_48_dialog_content = "Tidak perlu menyembunyikan detail apa pun dari kami. Cukup beri tahu kami apa yang Anda ketahui.",
  ui_story_31000601_49_dialog_content = "Semua orang mengatakan bahwa satu-satunya alasan rumah itu berhantu adalah karena putranya membunuh teman-temannya di sana!",
  ui_story_31000601_50_dialog_content = "Mungkinkah dia ingin dokter memeriksa mayat putranya untuk membuktikan bahwa dia tidak bersalah?",
  ui_story_31000601_51_dialog_content = "Saya khawatir Anda harus menanyakannya sendiri. Saya hanya mendengar tentang ini dari mendengarkan gosip pasien lain.",
  ui_story_31000601_52_dialog_content = "Anda akan melakukan klinik kami layanan yang hebat dengan membantunya menyelesaikan dilemanya.",
  ui_story_31000601_53_dialog_content = "M-Aku? Aku hanya ingin tahu tentang ceritanya, itu saja! Sedangkan untuk memeriksa mayat, aku... aku...",
  ui_story_31000601_54_dialog_content = "Saya akan memberi tahu dokter bahwa Anda yang menangani kasus ini. Saya yakin dia akan sangat berterima kasih atas bantuan Anda!",
  ui_story_31000601_55_dialog_content = "Apakah Anda pernah melakukan otopsi, Snowball?",
  ui_story_31000601_56_dialog_content = "T-Tidak pernah...",
  ui_story_31000601_57_dialog_content = "Tapi karena kita sudah tahu banyak tentang masalah ini, kurasa aku tidak bisa tidur di malam hari sampai aku mencapai dasarnya.",
  ui_story_31000601_58_dialog_content = "Anda akan membantunya?",
  ui_story_31000601_59_dialog_content = "Ya... Meskipun aku tidak tahu harus mulai dari mana atau menemukan koroner untuk melakukan otopsi...",
  ui_story_31000601_60_dialog_content = "Tetapi jika apa yang dikatakan perawat itu benar, saya tidak bisa hanya diam dan berpura-pura tidak mendengar apa-apa.",
  ui_story_31000601_61_dialog_content = "Saya hanya akan hidup untuk menyesalinya jika saya tidak membantu seorang ibu menemukan kedamaian setelah kehilangan putranya.",
  ui_story_31000601_62_dialog_content = "Heh... Itu Bola Salju yang selalu kukenal.",
  ui_story_31000601_63_dialog_content = "Maaf, Bu?",
  ui_story_31000601_64_dialog_content = "Ya? Dapatkah saya membantu Anda?",
  ui_story_31000601_65_dialog_content = "Saya punya permintaan untuk Anda. Aku butuh... *Berbisik*",
  ui_story_31000601_66_dialog_content = "Jika Anda bisa mendapatkan barang-barang itu untuk saya, kami akan dengan senang hati membantu Anda mengatasi kesulitan wanita itu.",
  ui_story_31000601_67_dialog_content = "B-Benarkah?! Tentu saja! Sebentar.",
  ui_story_31000601_68_dialog_content = "<color=#e8d9bb>Sepuluh menit kemudian...</color>",
  ui_story_31000601_69_dialog_content = "S-Sikare?!",
  ui_story_31000601_70_dialog_content = "Syukurlah aku tidak membuang seragam dokter wanita itu setelah dia pergi... Itu sangat cocok untukmu!",
  ui_story_31000601_71_dialog_content = "Koper ini memiliki setiap instrumen yang bisa saya minta. Terima kasih untuk bantuannya.",
  ui_story_31000601_72_dialog_content = "Dengan senang hati. Kami semua mengandalkan kalian berdua!",
  ui_story_31000601_73_dialog_content = "Tunggu... Apa kau sudah menjadi dokter selama ini, Sikare?!",
  ui_story_31000601_74_dialog_content = "Tergantung bagaimana Anda mendefinisikan seorang dokter ... ya, Anda bisa mengatakan itu.",
  ui_story_31000601_75_dialog_content = "Berbeda dengan dokter di klinik ini, saya mengkhususkan diri dalam merawat orang mati, bukan orang hidup.",
  ui_story_31000601_76_dialog_content = "Mendengarkan kata-kata mereka dan menyampaikannya selalu menjadi tugas saya.",
  ui_story_31000601_77_dialog_content = "Berarti kamu yang sempurna <color=#FFB400>dokter kematian</color> yang dibutuhkan wanita itu sekarang!",
  ui_story_31000601_78_dialog_content = "Itu sebabnya Anda memutuskan untuk mengenakan seragam dokter itu dan membantu saya menyelesaikan masalahnya, bukan?",
  ui_story_31000601_79_dialog_content = "Tentu saja... Kecuali ada orang lain dalam pikiranmu yang bersedia melakukan otopsi di rumah hantu?",
  ui_story_31000601_80_dialog_content = "Datang. Mari kita pergi mendengar apa yang dia katakan.",
  ui_story_31000601_81_dialog_content = "Hah? Tapi bagaimana dengan mengambil obat Anda?",
  ui_story_31000601_82_dialog_content = "Sesuatu memberi tahu saya bahwa masalah ini terkait dengan penyebab insomnia saya.",
  ui_story_31000601_83_dialog_content = "Mungkin dengan menyelesaikan masalahnya, kebisingan di sekitar Crypt juga akan berhenti.",
  ui_story_31000601_84_dialog_content = "Baiklah, mari kita bicara dengannya.",
  ui_story_31000601_85_dialog_content = "Tolong bantu anak saya ... Dia tidak bersalah, saya katakan ...",
  ui_story_31000601_86_dialog_content = "Dia tidak akan pernah membunuh seseorang...",
  ui_story_31000601_87_dialog_content = "Halo, Ibu. Perawat itu memberi tahu kami tentang situasi Anda.",
  ui_story_31000601_88_dialog_content = "Jika Anda tidak keberatan, bisakah Anda memberi tahu kami lebih banyak tentang apa yang terjadi dengan putra Anda?",
  ui_story_31000601_89_dialog_content = "Saya yakin kami mungkin dapat membantu Anda mengungkap kebenaran.",
  ui_story_31000601_90_dialog_content = "S-sungguh?",
  ui_story_31000601_91_dialog_content = "Maaf, tapi apakah Anda benar-benar seorang dokter? Dan apakah Anda benar-benar bersedia membantu saya?",
  ui_story_31000601_92_dialog_content = "Bagaimana jika saya memberi tahu Anda bahwa putra saya sudah mati? Apakah Anda masih ingin membantu saya?",
  ui_story_31000601_93_dialog_content = "Tentu saja. Justru karena alasan inilah saya bersedia meminjamkan bantuan saya kepada Anda.",
  ui_story_31000601_94_dialog_content = "Oh, syukurlah!",
  ui_story_31000601_95_dialog_content = "Akhirnya, seseorang yang bersedia membuktikan anak saya tidak bersalah!",
  ui_story_31000601_96_dialog_content = "Ambil semua uangku! Semua barang berharga saya! Saya akan membayar apa pun yang Anda minta, saya bersumpah!",
  ui_story_31000601_97_dialog_content = "Saya tidak membutuhkan uang atau barang berharga Anda. Mereka tidak melayani saya.",
  ui_story_31000601_98_dialog_content = "Kau tidak... akan menolakku, kan?",
  ui_story_31000601_99_dialog_content = "T-Tolong jangan salah paham! Yang dia maksud adalah dia tidak membutuhkan kompensasi finansial apa pun, itu saja!",
  ui_story_31000601_100_dialog_content = "Kami sudah setuju untuk membantu Anda, dan itulah yang kami rencanakan untuk dilakukan.",
  ui_story_31000601_101_dialog_content = "Sekarang, bisakah Anda memberi tahu kami lebih banyak tentang putra Anda dan situasinya?",
  ui_story_31000601_102_dialog_content = "Dan mengapa orang-orang datang dengan desas-desus tentang dia seperti itu?",
  ui_story_31000601_103_dialog_content = "Izinkan aku memulai dari awal...",
  ui_story_31000601_104_dialog_content = "Tiga hari yang lalu, putra saya memberi tahu saya bahwa teman-temannya berencana untuk menjelajahi sebuah rumah kosong di pinggiran kota.",
  ui_story_31000601_105_dialog_content = "Tetapi karena dia khawatir meninggalkan saya di rumah sendirian, dia mengatakan kepada mereka bahwa dia tidak bisa pergi.",
  ui_story_31000601_106_dialog_content = "Keesokan paginya, ketika dia menyadari bahwa teman-temannya belum pulang, dia menjadi khawatir.",
  ui_story_31000601_107_dialog_content = "Saya mengatakan kepadanya untuk tidak mengkhawatirkan saya dan dia harus pergi mencari teman-temannya.",
  ui_story_31000601_108_dialog_content = "Itu terakhir kali aku melihatnya.",
  ui_story_31000601_109_dialog_content = "Sudah tiga hari... Aku khawatir putramu dan teman-temannya telah lama tewas di dalam rumah.",
  ui_story_31000601_110_dialog_content = "Aku menunggunya sepanjang malam. Hingga sore hari berikutnya, dia masih belum pulang.",
  ui_story_31000601_111_dialog_content = "Pada saat itu, saya sudah tahu. Anak saya menghargai persahabatan di atas segalanya, Anda tahu. Dia lebih baik mati di sisi mereka daripada meninggalkan mereka.",
  ui_story_31000601_112_dialog_content = "Tapi tidak ada orang lain yang melihat itu. Bukannya ingin menemukan kebenaran, mereka menuduhnya membunuh teman-temannya dan memfitnah nama baiknya!",
  ui_story_31000601_113_dialog_content = "Anda tampaknya lebih peduli tentang kepolosan putra Anda daripada keadaan kematiannya.",
  ui_story_31000601_114_dialog_content = "Apakah ini sebabnya Anda ingin otopsi dilakukan padanya?",
  ui_story_31000601_115_dialog_content = "Itu juga hanya kami berdua. Dia adalah satu-satunya keluarga yang kutinggalkan.",
  ui_story_31000601_116_dialog_content = "Anda tidak tahu betapa sulitnya bagi saya untuk menerima bahwa dia telah pergi.",
  ui_story_31000601_117_dialog_content = "Tapi saya akan mengecewakannya jika saya tidak menemukan kebenaran dan membersihkan namanya!",
  ui_story_31000601_118_dialog_content = "Saya tahu bahwa saya pasti telah menyebabkan dokter itu tidak sedikit berduka, tetapi saya tidak tahu ke mana lagi harus berpaling ...",
  ui_story_31000601_119_dialog_content = "Saya tidak memiliki keahlian medis, dan bau darah membuat saya sangat pusing, saya bahkan tidak bisa mendekati rumah itu ...",
  ui_story_31000601_120_dialog_content = "Aku sangat ingin membantunya, Sikare... Aku juga ingin mengetahui kebenaran di balik rumah hantu itu.",
  ui_story_31000601_121_dialog_content = "Bagaimana denganmu? Apakah Anda percaya padanya?",
  ui_story_31000601_122_dialog_content = "Saya tidak percaya siapa pun. Saya menaruh kepercayaan saya hanya pada <color=#FFB400>kebenaran</color>.",
  ui_story_31000601_123_dialog_content = "Adapun <color=#FFB400>Kebenaran</color> tersembunyi dalam misteri ini... Kita hanya akan menemukan jawaban yang kita cari dengan berkonsultasi dengan arwah orang mati yang terperangkap di dalam rumah berhantu itu.",
  ui_story_31000601_124_dialog_content = "Tolong beri tahu kami di mana menemukan rumah itu.",
  ui_story_31000601_125_dialog_content = "Saya sangat lega bahwa Anda bersedia membantu.",
  ui_story_31000601_126_dialog_content = "Biarkan saya membawa Anda ke sana segera.",
  ui_story_31000601_127_dialog_content = "Setelah kita menemukan kebenarannya, mungkin akhirnya aku bisa membawanya pulang...",
  ui_story_31000601_128_dialog_content = "Baiklah.",
  ui_story_31000601_129_dialog_content = "Jangan buang waktu lagi. Silakan memimpin jalan!",
  ui_story_31000601_130_dialog_content = "Lebih dekat dan bau darah akan terlalu menyengat. Kami akan tetap di sini dan menunggumu, Sikare.",
  ui_story_31000601_131_dialog_content = "Sangat baik. Aku harus baik-baik saja sendiri.",
  ui_story_31000601_132_dialog_content = "Tolong jelaskan penampilan putra Anda kepada saya. Saya juga perlu mengumpulkan sampel darah jika Anda tidak keberatan.",
  ui_story_31000601_133_dialog_content = "Yakinlah, teknik saya sangat bagus. Saya tidak akan mengambil lebih banyak darah daripada yang diperlukan, dan Anda juga tidak akan mencium baunya.",
  ui_story_31000601_134_dialog_content = "Saya mengerti... Saya serahkan semuanya di tangan Anda yang cakap, Dokter.",
  ui_story_31000601_135_dialog_content = "<color=#e8d9bb>Dua puluh menit kemudian...</color>",
  ui_story_31000601_136_dialog_content = "Bagaimana keadaan disana, Sikare?",
  ui_story_31000601_137_dialog_content = "Tunggu... Kau tidak kembali dengan membawa apapun selain peralatan medismu? Apakah itu berarti putranya tidak ada di sana?",
  ui_story_31000601_138_dialog_content = "Apa maksudmu ada kemungkinan anakku... hidup?",
  ui_story_31000601_139_dialog_content = "Saya sangat menyesal, tetapi saya memang menemukan jenazah putra Anda di dalam rumah.",
  ui_story_31000601_140_dialog_content = "Karena mayatnya ditumpuk dengan banyak mayat lain, laju dekomposisinya sangat cepat.",
  ui_story_31000601_141_dialog_content = "Akibatnya, saya tidak dapat mengambil tubuhnya. Saya minta maaf.",
  ui_story_31000601_142_dialog_content = "Tidak apa-apa ... Saya sudah sangat bersyukur bahwa Anda bersedia membantu ...",
  ui_story_31000601_143_dialog_content = "Masih terlalu dini untuk berterima kasih padaku. Saya masih memiliki lebih banyak untuk dilaporkan.",
  ui_story_31000601_144_dialog_content = "Meskipun tubuhnya sudah sangat membusuk, saya dapat menggunakan sampel darah Anda untuk menemukan beberapa tulangnya.",
  ui_story_31000601_145_dialog_content = "Melalui tulang-tulang itu, aku bisa mendengar bisikan <color=#FFB400>kebenaran</color>.",
  ui_story_31000601_146_dialog_content = "<color=#e8d9bb>Tiga hari yang lalu...</color>",
  ui_story_31000601_147_dialog_content = "Grr... Graaah...",
  ui_story_31000601_148_dialog_content = "Graaah...!",
  ui_story_31000601_149_dialog_content = "Oh tidak... Apa kalian baik-baik saja? Katakan padaku aku tidak terlambat!",
  ui_story_31000601_150_dialog_content = "Apa yang kamu lakukan di sini?! Keluar, cepat! Selamatkan diri mu!",
  ui_story_31000601_151_dialog_content = "Kalau saja saya tidak menyarankan menjelajahi tempat ini, kami tidak akan sampai ke leher kami di Eclipsites. . .",
  ui_story_31000601_152_dialog_content = "Saya tidak tahu apa yang Anda lakukan di sini, tetapi tidak ada dari Anda yang harus membayar kesalahan saya.",
  ui_story_31000601_153_dialog_content = "Itu sebabnya saya akan tinggal di sini dan menahan mereka sementara kalian semua melarikan diri! Itu yang paling bisa saya lakukan!",
  ui_story_31000601_154_dialog_content = "Apakah Anda benar-benar berpikir saya tipe pria yang akan meninggalkan teman-temannya untuk mati?",
  ui_story_31000601_155_dialog_content = "Aku sudah di sini, bukan? Aku tidak akan kembali sendirian, sialan!",
  ui_story_31000601_156_dialog_content = "Jika ibuku pernah tahu bahwa aku tidak menghargai nyawa sahabatku...",
  ui_story_31000601_157_dialog_content = "Yah, saya tidak berpikir dia akan terlalu senang tentang itu.",
  ui_story_31000601_158_dialog_content = "Heh... Apa yang akan kami lakukan denganmu?",
  ui_story_31000601_159_dialog_content = "Aku bersumpah aku akan menebusnya untuk semua orang setelah kita keluar dari sini.",
  ui_story_31000601_160_dialog_content = "Ha! Saya akan melakukan apa pun untuk memastikan Anda menepati janji, kalau begitu!",
  ui_story_31000601_161_dialog_content = "Astaga!!",
  ui_story_31000601_162_dialog_content = "Greeeauuugh!!",
  ui_story_31000601_163_dialog_content = "Jadi Eclipsites mendapatkannya...",
  ui_story_31000601_164_dialog_content = "Memang. Setelah pencarian singkat, saya dapat menemukan sejumlah mayat yang baru saja meninggal... Saya yakin mereka adalah temannya.",
  ui_story_31000601_165_dialog_content = "Masing-masing dari mereka, tanpa diragukan lagi, dibantai oleh Eclipsites.",
  ui_story_31000601_166_dialog_content = "Ini berarti anakku tidak pernah menjadi pembunuh...",
  ui_story_31000601_167_dialog_content = "Benar. Juga, menurut penyelidikan saya, waktu kematiannya agak lebih lambat dari teman-temannya.",
  ui_story_31000601_168_dialog_content = "Mengingat keadaan jenazahnya yang rusak, tampaknya dia menderita serangan yang jauh lebih banyak daripada yang mereka alami.",
  ui_story_31000601_169_dialog_content = "Jadi dia benar-benar bertahan sampai akhir ...",
  ui_story_31000601_170_dialog_content = "Saya selalu tahu anak saya adalah anak yang baik... Dia melakukan semua yang dia bisa...",
  ui_story_31000601_171_dialog_content = "Jika ini adalah pilihan yang dia buat; jika ini yang hatinya suruh dia lakukan... Maka aku bisa menerimanya.",
  ui_story_31000601_172_dialog_content = "Jika ada yang namanya reinkarnasi, aku akan memilih menjadi ibunya lagi.",
  ui_story_31000601_173_dialog_content = "Terima kasih atas bantuan Anda berdua. Tolong izinkan saya untuk membayar Anda dengan benar atas masalah Anda.",
  ui_story_31000601_174_dialog_content = "Saya yakin anak saya juga menginginkan ini.",
  ui_story_31000601_175_dialog_content = "Sebutkan saja harga Anda, dan saya akan melakukan segala daya saya untuk memenuhinya.",
  ui_story_31000601_176_dialog_content = "Kami benar-benar tidak membutuhkan pembayaran, Bu. Kami senang—",
  ui_story_31000601_177_dialog_content = "Baiklah, tetapi ketahuilah bahwa Anda tidak dapat menarik kembali kata-kata Anda sekarang.",
  ui_story_31000601_178_dialog_content = "S-Sikare! Bukankah Anda mengatakan Anda hanya tertarik pada kebenaran sebelumnya ...?",
  ui_story_31000601_179_dialog_content = "Tidak, tidak apa-apa; setiap perbuatan baik layak mendapatkan imbalan. Tolong beritahu saya apa yang Anda inginkan sebagai pembayaran.",
  ui_story_31000601_180_dialog_content = "Ambil kartu nama ini. Saya ingin Anda menghubungi orang di dalamnya, dan mengatakan yang sebenarnya tentang apa yang terjadi di sini.",
  ui_story_31000601_181_dialog_content = "Hah?",
  ui_story_31000601_182_dialog_content = "Dia adalah jurnalis yang sangat profesional dan dapat dipercaya yang akan membuat kebenaran diketahui semua orang, bukan hanya kita.",
  ui_story_31000601_183_dialog_content = "Ini... Ini terlalu berlebihan... Kau sudah melakukan banyak hal untuk anakku dan aku...",
  ui_story_31000601_184_dialog_content = "Aku tidak melakukannya demi kamu. Sebagai <color=#FFB400>dokter kematian</color>, pekerjaan saya masih belum selesai.",
  ui_story_31000601_185_dialog_content = "Sampai batas tertentu, menyampaikan suara orang mati adalah cara lain untuk melestarikan hak-hak mereka yang selamat.",
  ui_story_31000601_186_dialog_content = "Sekarang saatnya untuk melakukan itu.",
  ui_story_31000601_187_dialog_content = "Anda tidak pernah menjadi ibu dari seorang pembunuh dan tidak punya alasan untuk bertahan dengan semua rumor tak berdasar ini lagi.",
  ui_story_31000601_188_dialog_content = "Sikare benar sekali. Setelah apa yang Anda dan putra Anda alami, Anda tidak perlu dihina seperti itu lagi.",
  ui_story_31000601_189_dialog_content = "Selain itu, Anda mengatakan Anda akan melakukan segala daya Anda untuk membayar apa yang kami minta, bukan?",
  ui_story_31000601_190_dialog_content = "Terima kasih... Kalian berdua. Aku akan memastikan untuk menceritakan semuanya padanya.",
  ui_story_31000601_191_dialog_content = "Bagus. Sekarang aku harus melakukan satu hal terakhir untuk mereka sebelum kita pergi.",
  ui_story_31000601_192_dialog_content = "Faria, dengarkan panggilanku... Buka gerbang Ruang Bawah Tanah, dan bimbing jiwa-jiwa malang ini ke tempat peristirahatan mereka yang layak.",
  ui_story_31000601_193_dialog_content = "Saya percaya saya akhirnya akan tidur nyenyak malam ini.",
  ui_story_31000601_194_dialog_content = "Semoga jiwa mereka menemukan bantuan dalam pelukan Kebenaran.",
  ui_story_31000602_1_dialog_content = "<color=#e8d9bb>... Glup, glup!</color>",
  ui_story_31000602_2_dialog_content = "Ugh... Ini menjijikkan...",
  ui_story_31000602_3_dialog_content = "Aku hampir tidak bisa bergerak... Meskipun rasanya seperti aku sedang berenang di air, rasanya seperti aku sama sekali tidak mengapung.",
  ui_story_31000602_4_dialog_content = "Aku hanya... tenggelam lebih dalam di bawah gelombang hitam ini, semakin jauh dari permukaan setiap detiknya...",
  ui_story_31000602_5_dialog_content = "Dan apa ini makhluk-makhluk yang mengelilingiku? Aku belum pernah melihat yang seperti mereka sebelumnya...",
  ui_story_31000602_6_dialog_content = "Indah... aneh... menyeramkan... Apakah aku akan menjadi makanan mereka?",
  ui_story_31000602_7_dialog_content = "Selamatkan... selamatkan aku...",
  ui_story_31000602_8_dialog_content = "Bola Salju... Bola Salju...",
  ui_story_31000602_9_dialog_content = "Apakah itu suara... yang memanggilku?",
  ui_story_31000602_10_dialog_content = "Aku... berdeguk, berdeguk... Aku di sini... berdeguk, berdeguk...",
  ui_story_31000602_11_dialog_content = "Jangan takut, aku datang...",
  ui_story_31000602_12_dialog_content = "!",
  ui_story_31000602_13_dialog_content = "S-Sikare?",
  ui_story_31000602_14_dialog_content = "Ini aku.",
  ui_story_31000602_15_dialog_content = "Bola Salju, apa yang kamu lakukan di sini?",
  ui_story_31000602_16_dialog_content = "Aku... berdeguk, berdeguk... Aku...",
  ui_story_31000602_17_dialog_content = "Saya mengerti. Mari kita bicara lebih banyak setelah kita sampai di pantai.",
  ui_story_31000602_18_dialog_content = "Silakan ikuti arah yang saya tunjukkan kepada Anda. Rasakan apungan dari gelombang.",
  ui_story_31000602_19_dialog_content = "Berdeguk, berdeguk...",
  ui_story_31000602_20_dialog_content = "Jangan takut, aku akan menggenggam tanganmu.",
  ui_story_31000602_21_dialog_content = "B-baiklah!",
  ui_story_31000602_22_dialog_content = "<color=#e8d9bb>Guyuran!</color>",
  ui_story_31000602_23_dialog_content = "Kami... Akhirnya kami berhasil keluar!",
  ui_story_31000602_24_dialog_content = "Tidak, aku belum bisa membiarkanmu keluar.",
  ui_story_31000602_25_dialog_content = "Anda belum menjawab pertanyaan sebelumnya saya.",
  ui_story_31000602_26_dialog_content = "Tergantung pada jawabanmu, aku mungkin saja membiarkanmu tenggelam ke dalam rawa lagi.",
  ui_story_31000602_27_dialog_content = "B-Baiklah! Tolong, dengarkan saja!",
  ui_story_31000602_28_dialog_content = "Apakah kamu membutuhkan sesuatu dariku, Snowball?",
  ui_story_31000602_29_dialog_content = "Hanya saja... Akhir-akhir ini, saya melihat kamu mengurung diri di kamar kamu di Colossus.",
  ui_story_31000602_30_dialog_content = "Kita jarang mendapatkan hari musim panas seperti ini... Apakah kamu tidak ingin ikut bersama semua orang untuk pergi ke pantai?",
  ui_story_31000602_31_dialog_content = "Maaf, tapi saya tidak memiliki rencana seperti itu.",
  ui_story_31000602_32_dialog_content = "Bola salju, kamu harus tahu bahwa hal-hal seperti itu tidak menarik bagi saya.",
  ui_story_31000602_33_dialog_content = "Ya, saya tahu, tetapi ada promosi khusus di Tir' Hotel sekarang.",
  ui_story_31000602_34_dialog_content = "Ada Aurorian lain seperti kamu di Colossus yang pada dasarnya tidak pernah keluar untuk bersenang-senang.",
  ui_story_31000602_35_dialog_content = "Ini mungkin adalah kesempatan terbaik yang akan saya dapatkan untuk membawa kalian semua ke pantai untuk menikmati laut, matahari, dan... pakaian renang...",
  ui_story_31000602_36_dialog_content = "Jadi, Snowball, kamu ingin melihat saya mengenakan baju renang, bukan?",
  ui_story_31000602_37_dialog_content = "Tidak, sama sekali bukan itu maksudku!",
  ui_story_31000602_38_dialog_content = "...",
  ui_story_31000602_39_dialog_content = "Lalu, tak ada lagi yang bisa kukatakan kepadamu. Tolong pergi.",
  ui_story_31000602_40_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian.</color>",
  ui_story_31000602_41_dialog_content = "Kita sudah pergi ke pantai dan kembali, tapi Sikare masih sendirian di Colossus...",
  ui_story_31000602_42_dialog_content = "Aku harus memeriksanya, setidaknya untuk bertanya apakah dia ingin oleh-oleh!",
  ui_story_31000602_43_dialog_content = "Hah? Kenapa pintunya dia terbuka?",
  ui_story_31000602_44_dialog_content = "Permisi... Hah? Dia tidak di sini?",
  ui_story_31000602_45_dialog_content = "Ini adalah... Black Box Sikare, Faria!",
  ui_story_31000602_46_dialog_content = "Apakah benar-benar baik-baik saja meninggalkannya di tanah seperti ini? Mungkin aku harus memungutnya untuknya...",
  ui_story_31000602_47_dialog_content = "<color=#e8d9bb>Klik-klak! Klik-klak!</color>",
  ui_story_31000602_48_dialog_content = "... Apakah benda ini bergerak?",
  ui_story_31000602_49_dialog_content = "<color=#e8d9bb>Klik-klak!</color>",
  ui_story_31000602_50_dialog_content = "Hah? Ahhhhhhh—",
  ui_story_31000602_51_dialog_content = "(Dan begitu, aku terjun ke dalam kegelapan, tenggelam tanpa henti, jatuh terus menerus...)",
  ui_story_31000602_52_dialog_content = "(Saat aku kembali sadar, aku sudah terperosok dalam rawa ini, sama sekali tidak bisa membebaskan diri...)",
  ui_story_31000602_53_dialog_content = "Jadi...",
  ui_story_31000602_54_dialog_content = "Apakah itu penjelasan Anda?",
  ui_story_31000602_55_dialog_content = "Ya... Ya, dan semua itu benar!",
  ui_story_31000602_56_dialog_content = "Aku hanya berpikir kamu mungkin sedikit kesepian sendirian di Colossus.",
  ui_story_31000602_57_dialog_content = "Aku pikir mungkin kamu akan berubah pikiran dan keluar bermain dengan semua orang!",
  ui_story_31000602_58_dialog_content = "Tolong jangan gunakan pemikiran sederhana itu untuk mengasumsikan pikiranku, seperti orang bodoh itu.",
  ui_story_31000602_59_dialog_content = "Apakah saya terlihat seperti orang yang begitu berubah-ubah?",
  ui_story_31000602_60_dialog_content = "Maaf... Maksudku bukan begitu!",
  ui_story_31000602_61_dialog_content = "Apakah aku maju dan berakhir di tempat yang seharusnya tidak aku datangi?",
  ui_story_31000602_62_dialog_content = "Kalau kamu benar-benar ingin tahu jawaban dari pertanyaan itu...",
  ui_story_31000602_63_dialog_content = "Bagaimana jika kamu bergabung denganku untuk berkeliling tempat ini?",
  ui_story_31000602_64_dialog_content = "Aku melihat ketakutan dan rasa ingin tahu di matamu. Kau pasti sangat tertarik dengan tempat ini, 'kan?",
  ui_story_31000602_65_dialog_content = "Ya. Rawa ini, dan makhluk serta tumbuhan yang ada di sini...",
  ui_story_31000602_66_dialog_content = "Aku belum pernah melihat sesuatu seperti mereka. Apakah tempat ini bisa jadi...",
  ui_story_31000602_67_dialog_content = "Benar. Ini adalah makam di dalam Starry Crypt.",
  ui_story_31000602_68_dialog_content = "Makhluk aneh yang telah kamu lihat adalah penjaga di sini.",
  ui_story_31000602_69_dialog_content = "Ketika kamu tenggelam ke dalam rawa sebelumnya, jika mereka merasakan ada permusuhan...",
  ui_story_31000602_70_dialog_content = "Mereka pasti akan melakukan segala yang mereka bisa untuk menghabisi kamu, penyusup.",
  ui_story_31000602_71_dialog_content = "Jadi... apakah aku baru saja lolos tipis dengan nyawa-nyawaku tadi?",
  ui_story_31000602_72_dialog_content = "Yakinlah, mereka tahu kamu tidak bermaksud jahat, dan mereka tidak akan mencoba mengancam hidupmu.",
  ui_story_31000602_73_dialog_content = "Jadi, Sikare, itu berarti... mereka tahu dari awal bahwa saya bukan penyusup!",
  ui_story_31000602_74_dialog_content = "Tentu saja, mereka juga mengandalkan penilaian mereka sendiri.",
  ui_story_31000602_75_dialog_content = "Beberapa penjarah makam sangat ahli dalam menyembunyikan niat mereka, tetapi kamu jelas tidak memiliki kecerdikan seperti itu, Snowball.",
  ui_story_31000602_76_dialog_content = "Rasa penasaranmu hampir meluap, menenggelamkan setiap jejak permusuhan.",
  ui_story_31000602_77_dialog_content = "Memangnya kelihatan dari wajahku?",
  ui_story_31000602_78_dialog_content = "Ini bukan hal yang buruk, Bola Salju.",
  ui_story_31000602_79_dialog_content = "Untuk seorang penjelajah sejati, pemandangan aneh dan fantastis ini adalah harta karun dalam haknya sendiri.",
  ui_story_31000602_80_dialog_content = "... Kamu benar tentang itu.",
  ui_story_31000602_81_dialog_content = "Sekarang aku punya kesempatan untuk melihat sekeliling dengan baik, pemandangan di sini benar-benar indah.",
  ui_story_31000602_82_dialog_content = "Sebuah keindahan yang misterius, etereal... Sangat berbeda dari pantai musim panas yang ramai dan berisik.",
  ui_story_31000602_83_dialog_content = "Apakah kamu sering berjalan di sekitar sini, Sikare?",
  ui_story_31000602_84_dialog_content = "Berjalan? \"Berpatroli\" akan menjadi kata kerja yang lebih tepat.",
  ui_story_31000602_85_dialog_content = "Seperti patroli hari ini, yang menghasilkan tangkapan yang sangat spesial—",
  ui_story_31000602_86_dialog_content = "A-Aku? Jadi Black Box menjeratku seperti aku adalah mangsanya?",
  ui_story_31000602_87_dialog_content = "Uh, ngomong-ngomong... Bukankah kita harus menangani Black Box di kamar Anda?",
  ui_story_31000602_88_dialog_content = "Hadapi itu?",
  ui_story_31000602_89_dialog_content = "Ya, lagi pula...",
  ui_story_31000602_90_dialog_content = "Aku tidak ingin merepotkanmu untuk menyelamatkan orang lain!",
  ui_story_31000602_91_dialog_content = "Kamu khawatir menggangguku?",
  ui_story_31000602_92_dialog_content = "Aku tidak percaya itu yang sebenarnya kamu pikirkan, Snowball...",
  ui_story_31000602_93_dialog_content = "Kamu khawatir jika teman-teman Aurorianmu bertindak sembrono dan mengganggu, hasilnya akan merepotkan untukmu, bukan?",
  ui_story_31000602_94_dialog_content = "Tentu saja, lebih baik jika tidak diganggu oleh orang lain!",
  ui_story_31000602_95_dialog_content = "Kamu tidak ingin diganggu?",
  ui_story_31000602_96_dialog_content = "Sepertinya kamu benar-benar suka pemandangan di sini, Snowball.",
  ui_story_31000602_97_dialog_content = "Kamu tidak ingin membagikannya dengan yang lain? Jarang sekali mendengar kamu menunjukkan sifat egois seperti ini...",
  ui_story_31000602_98_dialog_content = "Bukan itu maksudku...",
  ui_story_31000602_99_dialog_content = "Bukankah kamu bilang kamu lebih suka hidup yang damai?",
  ui_story_31000602_100_dialog_content = "Jika Aurorian lainnya benar-benar datang ke sini, tempat ini akan berakhir tidak berbeda dari resor pantai.",
  ui_story_31000602_101_dialog_content = "Anda telah mempertimbangkan aspek ini? Alasan yang layak bagi seseorang yang begitu dihargai oleh Lady Victoria.",
  ui_story_31000602_102_dialog_content = "Tapi biar aku jelaskan sesuatu—aku tidak memiliki keluhan tentang teman-teman kita, aku hanya tidak suka lingkungan yang berisik.",
  ui_story_31000602_103_dialog_content = "Jika ada seseorang yang diam-diam menemani saya, itu akan lebih baik daripada sendirian, sampai batas tertentu.",
  ui_story_31000602_104_dialog_content = "B-benarkah?",
  ui_story_31000602_105_dialog_content = "Sebenarnya, ini juga pertama kalinya aku memiliki kesempatan untuk menghargai betapa indahnya tempat ini di Starry Crypt. Aku belum pernah melihat tempat seperti ini sebelumnya!",
  ui_story_31000602_106_dialog_content = "Jika kamu tidak keberatan, aku ingin sering-sering datang ke sini untuk bergaul denganmu!",
  ui_story_31000602_107_dialog_content = "Hanya saja...",
  ui_story_31000602_108_dialog_content = "Ada kekhawatiran, Bola Salju?",
  ui_story_31000602_109_dialog_content = "Saya berharap ada cara yang lebih normal untuk masuk ke tempat ini... Saya tidak ingin menemukan diri saya tenggelam di rawa itu untuk kedua kalinya!",
  ui_story_31000602_110_dialog_content = "Jangan khawatir. Tidak peduli pintu masuk mana yang kamu datangi, atau makam mana yang kamu masuki...",
  ui_story_31000602_111_dialog_content = "Aku akan segera datang dan menemuimu.",
  ui_story_31000602_112_dialog_content = "Setelah semua, pintu masuk yang sebenarnya selalu ada di tangan saya.",
  ui_story_31000602_113_dialog_content = "Oh... Kamu sudah mengambil Kotak Hitammu? Kapan kamu—",
  ui_story_31000602_114_dialog_content = "Apa yang sedang kamu pikirkan, Bola Salju?",
  ui_story_31000602_115_dialog_content = "Apa kamu... Apa kamu masuk ke sini setelah aku?",
  ui_story_31000602_116_dialog_content = "Menarik. Kenapa kamu berpikir begitu?",
  ui_story_31000602_117_dialog_content = "Nah, kamu tidak punya waktu untuk kembali dan mengambil Kotak Hitam, dan...",
  ui_story_31000602_118_dialog_content = "Kamu biasanya tidak akan berganti menjadi <color=#FFB400>baju renang</color> saat patroli, bukan? Jadi apakah itu berarti...",
  ui_story_31000602_119_dialog_content = "So, Snowball, you wish to see me in a swimsuit, do you?",
  ui_story_31000602_120_dialog_content = "No, that's not what I meant at all!",
  ui_story_31000602_121_dialog_content = "Apakah ini karena apa yang saya katakan sebelumnya?",
  ui_story_31000602_122_dialog_content = "Tolong jangan gunakan pemikiran sederhana itu untuk mengasumsikan motif saya, seperti orang bodoh itu.",
  ui_story_31000602_123_dialog_content = "Ini hanya hasil dari kehendak saya sendiri, atau mungkin sebuah keinginan sesaat.",
  ui_story_31000602_124_dialog_content = "Aku tidak ingin dilihat oleh orang-orang bodoh itu, juga tidak ingin dinilai oleh mereka.",
  ui_story_31000602_125_dialog_content = "Jadi aku hanya mengganti pakaian menjadi baju renang di sini saja. Mengerti?",
  ui_story_31000602_126_dialog_content = "Tapi... itu benar-benar terlihat bagus padamu.",
  ui_story_31000602_127_dialog_content = "Dibandingkan dengan makhluk ajaib dan tanaman tersebut...",
  ui_story_31000602_128_dialog_content = "Bahkan, aku akan berani mengatakan bahwa kamu lebih cantik.",
  ui_story_31000602_129_dialog_content = "...",
  ui_story_31000602_130_dialog_content = "Sejak kapan saya mengizinkan Anda untuk memusatkan rasa penasaran Anda pada saya?",
  ui_story_31000602_131_dialog_content = "Meski tanpa membawa permusuhan, jika kamu lengah dan melanggar hukum-hukum Crypt...",
  ui_story_31000602_132_dialog_content = "Kamu mungkin masih bisa menemukan dirimu terseret ke dalam jurang oleh tendril-tendril gelap ini, menjadi hiasan permanen di sini di dalam makam.",
  ui_story_31000602_133_dialog_content = "Bukankah itu sedikit terlalu jauh?",
  ui_story_31000602_134_dialog_content = "Takut?",
  ui_story_31000602_135_dialog_content = "Sedikit... dan benar-benar agak khawatir!",
  ui_story_31000602_136_dialog_content = "Reaksimu, Snowball... sungguh sangat lucu.",
  ui_story_31000602_137_dialog_content = "Jangan khawatir, aku akan melindungimu. <size=30>Setelah semua, yang bisa membebaskan saya dari belenggu ruang bawah tanah...</size>",
  ui_story_31000602_138_dialog_content = "Apa?",
  ui_story_31000602_139_dialog_content = "Aku bilang... Sini, mendekatlah. Lebih dekat.",
  ui_story_31000602_140_dialog_content = "Untuk keselamatanmu, Bola Salju, saat berada di dalam kripta, kamu harus <color=#FFB400>selalu</color> berada dekat denganku.",
  ui_story_31000602_141_dialog_content = "Paham?",
  ui_story_31000602_142_dialog_content = "Oke, aku tidak akan meninggalkanmu! Aku janji aku akan tetap di sisimu!"
}
return config
